import ExcelJS from 'exceljs';
import * as path from 'path';

/**
 * One-time/CI-time generator for sample test data.
 * Run with: npm run generate:testdata:saucedemo
 * In real projects this file is typically maintained by hand/by testers,
 * not regenerated by a script - this exists purely to make the repo runnable out of the box.
 */
async function generateSampleData(): Promise<void> {
  const workbook = new ExcelJS.Workbook();

  const loginSheet = workbook.addWorksheet('LoginData');
  loginSheet.columns = [
    { header: 'testCaseId', key: 'testCaseId', width: 15 },
    { header: 'username', key: 'username', width: 20 },
    { header: 'password', key: 'password', width: 20 },
    { header: 'expectedResult', key: 'expectedResult', width: 15 },
    { header: 'run', key: 'run', width: 8 },
  ];
  loginSheet.addRows([
    { testCaseId: 'TC_LOGIN_01', username: 'standard_user', password: 'secret_sauce', expectedResult: 'success', run: 'Y' },
    { testCaseId: 'TC_LOGIN_02', username: 'locked_out_user', password: 'secret_sauce', expectedResult: 'locked', run: 'Y' },
    { testCaseId: 'TC_LOGIN_03', username: 'standard_user', password: 'wrong_password', expectedResult: 'invalid', run: 'Y' },
    { testCaseId: 'TC_LOGIN_04', username: '', password: 'secret_sauce', expectedResult: 'missingUsername', run: 'Y' },
  ]);

  const checkoutSheet = workbook.addWorksheet('CheckoutData');
  checkoutSheet.columns = [
    { header: 'testCaseId', key: 'testCaseId', width: 15 },
    { header: 'product', key: 'product', width: 25 },
    { header: 'firstName', key: 'firstName', width: 15 },
    { header: 'lastName', key: 'lastName', width: 15 },
    { header: 'postalCode', key: 'postalCode', width: 15 },
    { header: 'expectedResult', key: 'expectedResult', width: 18 },
    { header: 'expectedMessage', key: 'expectedMessage', width: 30 },
    { header: 'stepOneMessage', key: 'stepOneMessage', width: 30 },
    { header: 'stepTwoMessage', key: 'stepTwoMessage', width: 30 },
    { header: 'stepThreeMessage', key: 'stepThreeMessage', width: 30 },
    { header: 'apiJobTitle', key: 'apiJobTitle', width: 20 },
    { header: 'run', key: 'run', width: 8 },
  ];
  checkoutSheet.addRows([
    { testCaseId: 'TC_CHECKOUT_01', product: 'Sauce Labs Backpack', firstName: 'Jane', lastName: 'Doe', postalCode: '380001', expectedResult: 'success', expectedMessage: '', stepOneMessage: '', stepTwoMessage: '', stepThreeMessage: '', apiJobTitle: 'QA Automation Lead', run: 'Y' },
    { testCaseId: 'TC_CHECKOUT_02', product: 'Sauce Labs Backpack', firstName: 'John', lastName: 'Smith', postalCode: '10001', expectedResult: 'success', expectedMessage: '', stepOneMessage: '', stepTwoMessage: '', stepThreeMessage: '', apiJobTitle: 'Software Engineer', run: 'Y' },
    { testCaseId: 'TC_CHECKOUT_03', product: 'Sauce Labs Backpack', firstName: '', lastName: 'Doe', postalCode: '12345', expectedResult: 'missingFirstName', expectedMessage: 'First Name is required', stepOneMessage: '', stepTwoMessage: '', stepThreeMessage: '', apiJobTitle: '', run: 'Y' },
    { testCaseId: 'TC_CHECKOUT_04', product: 'Sauce Labs Backpack', firstName: 'John', lastName: '', postalCode: '10001', expectedResult: 'missingLastName', expectedMessage: 'Last Name is required', stepOneMessage: '', stepTwoMessage: '', stepThreeMessage: '', apiJobTitle: '', run: 'Y' },
    { testCaseId: 'TC_CHECKOUT_05', product: 'Sauce Labs Backpack', firstName: 'John', lastName: 'Doe', postalCode: '', expectedResult: 'missingPostalCode', expectedMessage: 'Postal Code is required', stepOneMessage: '', stepTwoMessage: '', stepThreeMessage: '', apiJobTitle: '', run: 'Y' },
    { testCaseId: 'TC_CHECKOUT_06', product: 'Sauce Labs Backpack', firstName: 'John', lastName: 'Doe', postalCode: '', expectedResult: 'sequentialValidation', expectedMessage: '', stepOneMessage: 'First Name is required', stepTwoMessage: 'Last Name is required', stepThreeMessage: 'Postal Code is required', apiJobTitle: '', run: 'Y' },
  ]);

  const sortingSheet = workbook.addWorksheet('SortingData');
  sortingSheet.columns = [
    { header: 'testCaseId', key: 'testCaseId', width: 15 },
    { header: 'sortOption', key: 'sortOption', width: 12 },
    { header: 'sortLabel', key: 'sortLabel', width: 22 },
    { header: 'run', key: 'run', width: 8 },
  ];
  sortingSheet.addRows([
    { testCaseId: 'TC_SORT_01', sortOption: 'az', sortLabel: 'Name (A to Z)', run: 'Y' },
    { testCaseId: 'TC_SORT_02', sortOption: 'za', sortLabel: 'Name (Z to A)', run: 'Y' },
    { testCaseId: 'TC_SORT_03', sortOption: 'lohi', sortLabel: 'Price (low to high)', run: 'Y' },
    { testCaseId: 'TC_SORT_04', sortOption: 'hilo', sortLabel: 'Price (high to low)', run: 'Y' },
  ]);

  const outputPath = path.resolve(__dirname, '../data/testdata.xlsx');
  await workbook.xlsx.writeFile(outputPath);
  // eslint-disable-next-line no-console
  console.log(`Sample test data written to ${outputPath}`);
}

generateSampleData().catch((err) => {
  // eslint-disable-next-line no-console
  console.error(err);
  process.exit(1);
});
